/**
 * 디자인 시스템 아이콘 세트 — 피그마 Components/Icon 심볼 1:1
 * 위치: src/components/icons.tsx
 *
 * 시안에서 export한 24×24 SVG의 경로 데이터를 그대로 사용하고
 * 색만 currentColor로 바꿔 부모 텍스트 색을 따른다.
 * 크기는 size prop(px, 기본 24)으로 제어. 나머지 svg 속성은 스프레드로 전달.
 */

import type { SVGProps } from "react";

type IconProps = SVGProps<SVGSVGElement> & { size?: number };

function IconBase({
  size = 24,
  children,
  ...props
}: IconProps & { children: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      {...props}
    >
      {children}
    </svg>
  );
}

/* 시안의 스트로크 프리셋 3종 */
const s16 = {
  stroke: "currentColor",
  strokeWidth: 1.6,
  strokeLinecap: "round",
  strokeLinejoin: "round",
} as const;
/* 투박함 완화 조정(사용자 결정): 시안 원본 1.8→1.6, 2.4→2.0 */
const s16cap = { stroke: "currentColor", strokeWidth: 1.6, strokeLinecap: "round" } as const;
const s20 = { stroke: "currentColor", strokeWidth: 2, strokeLinecap: "round" } as const;
const sJoin16 = { stroke: "currentColor", strokeWidth: 1.6, strokeLinejoin: "round" } as const;

